{"path": "/tmp/sv-e048644ab0a64bfdb86a18a9e85f6813/Components/Pages/Settings/ChangePasswordPanel.razor", "file_text": "<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center"
         role="button" @onclick="() => _expanded = !_expanded"
         style="cursor:pointer;">
        <h6 class="mb-0">Change Password</h6>
        <span>@(_expanded ? "▲" : "▼")</span>
    </div>

    @if (_expanded)
    {
        <div class="card-body">
            @if (!string.IsNullOrEmpty(_statusMessage))
            {
                <div class="alert @(_isError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
                    @_statusMessage
                    <button type="button" class="btn-close" @onclick="() => _statusMessage = null"></button>
                </div>
            }

            <div class="mb-3">
                <label class="form-label fw-semibold">Current Password</label>
                <input type="password" class="form-control" @bind="_currentPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label fw-semibold">New Password</label>
                <input type="password" class="form-control" @bind="_newPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label fw-semibold">Confirm New Password</label>
                <input type="password" class="form-control @(_confirmError ? "is-invalid" : "")"
                       @bind="_confirmPassword" />
                @if (_confirmError)
                {
                    <div class="invalid-feedback">Passwords do not match.</div>
                }
            </div>

            <button class="btn btn-warning" @onclick="UpdatePasswordAsync" disabled="@_saving">
                @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Update Password
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public EventCallback<(string Current, string New)> OnChangePassword { get; set; }

    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _expanded;
    private bool _saving;
    private bool _confirmError;
    private string? _statusMessage;
    private bool _isError;

    private async Task UpdatePasswordAsync()
    {
        _confirmError = false;
        _statusMessage = null;

        if (_newPassword != _confirmPassword)
        {
            _confirmError = true;
            return;
        }

        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            _statusMessage = "Please fill in all password fields.";
            _isError = true;
            return;
        }

        _saving = true;
        try
        {
            await OnChangePassword.InvokeAsync((_currentPassword, _newPassword));
            _statusMessage = "Password updated successfully!";
            _isError = false;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch
        {
            _statusMessage = "Failed to update password. Please try again.";
            _isError = true;
        }
        finally
        {
            _saving = false;
        }
    }
}
"}

