+        <div class="mb-3 form-check form-switch">
+            <input type="checkbox" class="form-check-input" id="weeklyDigest" @bind="_weeklyDigest" />
+            <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
+        </div>
+
+        <hr />
+
+        <h6 class="mb-3">Muted Channels</h6>
+        <div class="row row-cols-1 row-cols-md-2 g-2 mb-4">
+            @foreach (var channel in AvailableChannels)
+            {
+                var isMuted = _mutedChannels.Contains(channel);
+                <div class="col">
+                    <div class="form-check">
+                        <input type="checkbox" class="form-check-input"
+                               id="@($"ch-{channel}")"
+                               checked="@isMuted"
+                               @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
+                        <label class="form-check-label" for="@($"ch-{channel}")">@channel</label>
+                    </div>
+                </div>
+            }
+        </div>
+
+        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
+            @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
+            Save Preferences
+        </button>
+    </div>
+</div>
+
+@code {
+    [Parameter, EditorRequired] public NotificationPrefs? Prefs { get; set; }
+    [Parameter, EditorRequired] public EventCallback<NotificationPrefs> OnSave { get; set; }
+
+    private static readonly string[] AvailableChannels =
+        ["General", "Announcements", "Updates", "Marketing", "Engineering", "Support"];
+
+    private bool _emailNotifications;
+    private bool _pushNotifications;
+    private bool _weeklyDigest;
+    private HashSet<string> _mutedChannels = new();
+    private bool _saving;
+    private string? _statusMessage;
+
+    protected override void OnParametersSet()
+    {
+        if (Prefs is not null && !_saving)
+        {
+            _emailNotifications = Prefs.EmailNotifications;
+            _pushNotifications = Prefs.PushNotifications;
+            _weeklyDigest = Prefs.WeeklyDigest;
+            _mutedChannels = new HashSet<string>(Prefs.MutedChannels);
+        }
+    }
+
+    private void ToggleChannel(string channel, bool muted)
+    {
+        if (muted) _mutedChannels.Add(channel);
+        else _mutedChannels.Remove(channel);
+    }
+
+    private async Task SaveAsync()
+    {
+        _saving = true;
+        _statusMessage = null;
+        try
+        {
+            var updated = new NotificationPrefs(
+                _emailNotifications, _pushNotifications, _weeklyDigest,
+                _mutedChannels.ToList());
+            await OnSave.InvokeAsync(updated);
+            _statusMessage = "Notification preferences saved!";
+        }
+        finally
+        {
+            _saving = false;
+        }
+    }
+}
+

