@using sv_e048644ab0a64bfdb86a18a9e85f6813.Models

<div class="card">
    <div class="card-header"><h5 class="mb-0">Security Settings</h5></div>
    <div class="card-body">
        @if (Security is null)
        {
            <p class="text-muted">Loading security settings…</p>
            return;
        }

        <ChangePasswordPanel OnChangePassword="OnChangePassword" />

        <div class="card mb-3">
            <div class="card-body">
                <div class="d-flex justify-content-between align-items-center">
                    <div>
                        <h6 class="mb-1">Two-Factor Authentication</h6>
                        <span class="badge @(Security.TwoFactorEnabled ? "bg-success" : "bg-secondary")">
                            @(Security.TwoFactorEnabled ? "Enabled" : "Disabled")
                        </span>
                    </div>
                    <div class="form-check form-switch">
                        <input type="checkbox" class="form-check-input" id="twoFactor"
                               checked="@Security.TwoFactorEnabled" disabled
                               aria-label="Two-factor authentication status" />
                    </div>
                </div>
                @if (Security.LastPasswordChange.HasValue)
                {
                    <small class="text-muted d-block mt-2">
                        Last password change: @Security.LastPasswordChange.Value.ToString("MMMM d, yyyy")
                    </small>
                }
            </div>
        </div>

        <div class="card">
            <div class="card-header"><h6 class="mb-0">Active Sessions</h6></div>
            <div class="card-body p-0">
                <div class="table-responsive">
                    <table class="table table-hover mb-0">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th class="text-end">Action</th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in Security.Sessions)
                            {
                                var isCurrent = session.Id == _currentSessionId;
                                <tr>
                                    <td>
                                        @session.Device
                                        @if (isCurrent) { <span class="badge bg-info ms-1">Current</span> }
                                    </td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td class="text-end">
                                        @if (!isCurrent)
                                        {
                                            <button class="btn btn-outline-danger btn-sm"
                                                    @onclick="() => _sessionToRevoke = session">
                                                Revoke
                                            </button>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    </div>
</div>

<RevokeSessionDialog Session="_sessionToRevoke"
                      OnConfirm="ConfirmRevokeAsync"
                      OnCancel="() => _sessionToRevoke = null" />

@code {
    [Parameter, EditorRequired] public SecuritySettings? Security { get; set; }
    [Parameter, EditorRequired]
    public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter, EditorRequired] public EventCallback<string> OnRevokeSession { get; set; }

    private ActiveSession? _sessionToRevoke;
    private string? _currentSessionId;

    protected override void OnParametersSet()
    {
        // Treat the most recently active session as the current one
        if (Security?.Sessions is { Count: > 0 })
        {
            _currentSessionId = Security.Sessions
                .OrderByDescending(s => s.LastActive)
                .First().Id;
        }
    }

    private async Task ConfirmRevokeAsync(string sessionId)
    {
        _sessionToRevoke = null;
        await OnRevokeSession.InvokeAsync(sessionId);
    }

    private static string FormatLastActive(DateTime dt)
    {
        var elapsed = DateTime.UtcNow - dt;
        if (elapsed.TotalMinutes < 1) return "Just now";
        if (elapsed.TotalHours < 1) return $"{(int)elapsed.TotalMinutes}m ago";
        if (elapsed.TotalDays < 1) return $"{(int)elapsed.TotalHours}h ago";
        return dt.ToString("MMM d, yyyy");
    }
}

@using sv_e048644ab0a64bfdb86a18a9e85f6813.Models

<div class="card">
    <div class="card-header"><h5 class="mb-0">Appearance</h5></div>
    <div class="card-body">
        @if (Settings is null)
        {
            <p class="text-muted">Loading appearance settings…</p>
            return;
        }

        @if (!string.IsNullOrEmpty(_statusMessage))
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @_statusMessage
                <button type="button" class="btn-close" @onclick="() => _statusMessage = null"></button>
            </div>
        }

        <div class="row">
            <div class="col-md-6">
                <div class="mb-4">
                    <h6 class="mb-2">Theme</h6>
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <div class="form-check">
                            <input type="radio" class="form-check-input" name="theme"
                                   id="@($"theme-{theme}")"
                                   value="@theme"
                                   checked="@(_theme == theme)"
                                   @onchange="() => _theme = theme" />
                            <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                        </div>
                    }
                </div>

                <div class="mb-4">
                    <h6 class="mb-2">Font Size</h6>
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <div class="form-check">
                            <input type="radio" class="form-check-input" name="fontSize"
                                   id="@($"fs-{size}")"
                                   value="@size"
                                   checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                        </div>
                    }
                </div>

                <div class="mb-4">
                    <h6 class="mb-2">Language</h6>
                    <select class="form-select" @bind="_language">
                        <option value="en">English</option>
                        <option value="es">Español</option>
                        <option value="fr">Français</option>
                        <option value="de">Deutsch</option>
                        <option value="ja">日本語</option>
                        <option value="zh">中文</option>
                    </select>
                </div>

                <div class="mb-4 form-check form-switch">
                    <input type="checkbox" class="form-check-input" id="compactMode" @bind="_compactMode" />
                    <label class="form-check-label" for="compactMode">Compact Mode</label>
                </div>

                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Save
                </button>
            </div>

            <div class="col-md-6">
                <h6 class="mb-2">Live Preview</h6>
                <div class="border rounded @PreviewBgClass" style="@PreviewStyle">
                    <div class="@PreviewPaddingClass">
                        <div class="d-flex align-items-center mb-2">
                            <div class="rounded-circle me-2 @PreviewAccentClass"
                                 style="width:32px;height:32px;"></div>
                            <div>
                                <strong style="@PreviewTextStyle">Jane Doe</strong><br />
                                <small class="@PreviewMutedClass">jane.doe@example.com</small>
                            </div>
                        </div>
                        <hr class="@PreviewBorderClass" />
                        <p class="mb-1" style="@PreviewTextStyle">
                            This is a preview of how your settings will look.
                        </p>
                        <div class="d-flex gap-2 mt-2">
                            <button class="btn btn-sm @PreviewBtnClass" disabled>Primary</button>
                            <button class="btn btn-sm @PreviewBtnOutlineClass" disabled>Secondary</button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public AppearanceSettings? Settings { get; set; }
    [Parameter, EditorRequired] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;
    private bool _saving;
    private string? _statusMessage;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_saving)
        {
            _theme = Settings.Theme;
            _fontSize = Settings.FontSize;
            _language = Settings.Language;
            _compactMode = Settings.CompactMode;
        }
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _statusMessage = null;
        try
        {
            var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
            await OnSave.InvokeAsync(updated);
            _statusMessage = "Appearance settings saved!";
        }
        finally
        {
            _saving = false;
        }
    }

    // Preview computed properties
    private string PreviewFontSize => _fontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.15rem",
        _ => "1rem"
    };

    private bool IsDark => _theme == "Dark";

    private string PreviewStyle =>
        $"font-size:{PreviewFontSize};min-height:200px;" +
        (IsDark ? "background:#1e1e2e;color:#cdd6f4;" : "background:#ffffff;color:#212529;");

    private string PreviewTextStyle => IsDark ? "color:#cdd6f4;" : "color:#212529;";
    private string PreviewBgClass => IsDark ? "" : "bg-light";
    private string PreviewPaddingClass => _compactMode ? "p-2" : "p-3";
    private string PreviewAccentClass => IsDark ? "bg-primary" : "bg-primary";
    private string PreviewMutedClass => IsDark ? "text-light opacity-50" : "text-muted";
    private string PreviewBorderClass => IsDark ? "border-secondary" : "";
    private string PreviewBtnClass => IsDark ? "btn-light" : "btn-primary";
    private string PreviewBtnOutlineClass => IsDark ? "btn-outline-light" : "btn-outline-primary";
}

@page "/settings"
@using sv_e048644ab0a64bfdb86a18a9e85f6813.Models
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<h3 class="mb-4">⚙️ Settings</h3>

<div class="row">
    <div class="col-md-3 col-lg-2 mb-3">
        <SettingsSidebar ActiveSection="@_activeSection"
                         OnSectionChanged="s => _activeSection = s" />
    </div>

    <div class="col-md-9 col-lg-10">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection Profile="@_profile" OnSave="SaveProfileAsync" />
                break;

            case "Notifications":
                <NotificationsSection Prefs="@_notificationPrefs" OnSave="SaveNotificationsAsync" />
                break;

            case "Security":
                <SecuritySection Security="@_security"
                                 OnChangePassword="ChangePasswordAsync"
                                 OnRevokeSession="RevokeSessionAsync" />
                break;

            case "Appearance":
                <AppearanceSection Settings="@_appearance" OnSave="SaveAppearanceAsync" />
                break;
        }
    </div>
</div>

@code {
    private string _activeSection = "Profile";
    private UserProfile? _profile;
    private NotificationPrefs? _notificationPrefs;
    private SecuritySettings? _security;
    private AppearanceSettings? _appearance;

    protected override async Task OnInitializedAsync()
    {
        // Load all sections in parallel
        var profileTask = SettingsService.GetProfileAsync();
        var notifsTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifsTask, securityTask, appearanceTask);

        _profile = profileTask.Result;
        _notificationPrefs = notifsTask.Result;
        _security = securityTask.Result;
        _appearance = appearanceTask.Result;
    }

    private async Task SaveProfileAsync(UserProfile updated)
    {
        await SettingsService.SaveProfileAsync(updated);
        _profile = updated;
    }

    private async Task SaveNotificationsAsync(NotificationPrefs updated)
    {
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _notificationPrefs = updated;
    }

    private async Task ChangePasswordAsync((string Current, string New) passwords)
    {
        await SettingsService.ChangePasswordAsync(passwords.Current, passwords.New);
        _security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearanceAsync(AppearanceSettings updated)
    {
        await SettingsService.SaveAppearanceAsync(updated);
        _appearance = updated;
    }
}

