@code {
    [Parameter, EditorRequired] public AppearanceSettings? Settings { get; set; }
    [Parameter, EditorRequired] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;
    private bool _saving;
    private string? _statusMessage;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_saving)
        {
            _theme = Settings.Theme;
            _fontSize = Settings.FontSize;
            _language = Settings.Language;
            _compactMode = Settings.CompactMode;
        }
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _statusMessage = null;
        try
        {
            var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
            await OnSave.InvokeAsync(updated);
            _statusMessage = "Appearance settings saved!";
        }
        finally
        {
            _saving = false;
        }
    }

    // Preview computed properties
    private string PreviewFontSize => _fontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.15rem",
        _ => "1rem"
    };

    private bool IsDark => _theme == "Dark";

    private string PreviewStyle =>
        $"font-size:{PreviewFontSize};min-height:200px;" +
        (IsDark ? "background:#1e1e2e;color:#cdd6f4;" : "background:#ffffff;color:#212529;");

    private string PreviewTextStyle => IsDark ? "color:#cdd6f4;" : "color:#212529;";
    private string PreviewBgClass => IsDark ? "" : "bg-light";
    private string PreviewPaddingClass => _compactMode ? "p-2" : "p-3";
    private string PreviewAccentClass => IsDark ? "bg-primary" : "bg-primary";
    private string PreviewMutedClass => IsDark ? "text-light opacity-50" : "text-muted";
    private string PreviewBorderClass => IsDark ? "border-secondary" : "";
    private string PreviewBtnClass => IsDark ? "btn-light" : "btn-primary";
    private string PreviewBtnOutlineClass => IsDark ? "btn-outline-light" : "btn-outline-primary";
}

